insert into public.restaurants (owner_id, slug, name, phone, email, settings, is_demo, is_template) values (null, 'demo-restaurant-template', 'Demo Restaurant', '+91 98765 43210', 'hello@trattoriademo.example', '{"name":"Demo Restaurant","phone":"+91 98765 43210","email":"hello@trattoriademo.example","tables":12,"seatsPerTable":4,"mealMinutes":90,"maxPartySize":8,"days":{"monday":{"open":false,"lunch":{"on":false,"start":"12:00","end":"15:00"},"dinner":{"on":true,"start":"17:00","end":"22:00"}},"tuesday":{"open":true,"lunch":{"on":false,"start":"12:00","end":"15:00"},"dinner":{"on":true,"start":"17:00","end":"22:00"}},"wednesday":{"open":true,"lunch":{"on":false,"start":"12:00","end":"15:00"},"dinner":{"on":true,"start":"17:00","end":"22:00"}},"thursday":{"open":true,"lunch":{"on":false,"start":"12:00","end":"15:00"},"dinner":{"on":true,"start":"17:00","end":"22:00"}},"friday":{"open":true,"lunch":{"on":false,"start":"12:00","end":"15:00"},"dinner":{"on":true,"start":"17:00","end":"23:00"}},"saturday":{"open":true,"lunch":{"on":false,"start":"12:00","end":"15:00"},"dinner":{"on":true,"start":"17:00","end":"23:00"}},"sunday":{"open":true,"lunch":{"on":false,"start":"12:00","end":"15:00"},"dinner":{"on":true,"start":"17:00","end":"21:00"}}}}'::jsonb, true, true);
insert into public.reviews (restaurant_id, demo_key, author, rating, date, text, source, claims) values
((select id from public.restaurants where is_template), 'g1', 'Priya S.', 3, '2026-10-16T09:00:00', 'We went on Thursday around 6:30 PM, party of 4. The food was good but we waited about 35 minutes just for our appetizers and nobody told us why. Service was friendly once things arrived.', 'demo', '[{"party_size":4,"weekday":"thursday","date":null,"time":"18:30","item":null,"text":"We went on Thursday around 6:30 PM, party of 4.","type":"party_size"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"waited about 35 minutes just for our appetizers","type":"wait_time"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":"appetizers","text":"appetizers","type":"item_ordered"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"nobody told us why","type":"staff"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"Service was friendly","type":"staff"}]'::jsonb),
((select id from public.restaurants where is_template), 'g2', 'Marcus T.', 2, '2026-10-15T12:00:00', 'Dinner on Tuesday at about 7 PM, just the two of us. I asked for my steak medium and it came out well done and dry. The server offered to remake it but we were already hungry and it felt rushed.', 'demo', '[{"party_size":2,"weekday":"tuesday","date":null,"time":"19:00","item":null,"text":"Dinner on Tuesday at about 7 PM, just the two of us","type":"party_size"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":"steak","text":"my steak","type":"item_ordered"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"well done and dry","type":"food_quality"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"it felt rushed","type":"staff"}]'::jsonb),
((select id from public.restaurants where is_template), 'g3', 'Elena R.', 2, '2026-10-19T08:00:00', 'Sunday evening, around 6 PM, party of 3. We waited close to 40 minutes for our mains and the soup arrived lukewarm. The staff was apologetic but it was disappointing for the price.', 'demo', '[{"party_size":3,"weekday":"sunday","date":null,"time":"18:00","item":null,"text":"Sunday evening, around 6 PM, party of 3","type":"party_size"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"waited close to 40 minutes for our mains","type":"wait_time"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"the soup arrived lukewarm","type":"food_quality"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"The staff was apologetic","type":"staff"}]'::jsonb),
((select id from public.restaurants where is_template), 'm1', 'Dan K.', 1, '2026-10-19T14:00:00', 'Our table of 10 on Friday around 8 PM was completely ignored. We waited an hour and nobody took our order. Absolutely the worst service I have ever experienced.', 'demo', '[{"party_size":10,"weekday":"friday","date":null,"time":"20:00","item":null,"text":"table of 10 on Friday around 8 PM","type":"party_size"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"completely ignored","type":"staff"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"waited an hour","type":"wait_time"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"nobody took our order","type":"staff"}]'::jsonb),
((select id from public.restaurants where is_template), 'm2', 'Chris W.', 2, '2026-10-21T09:00:00', 'Stopped in for a quick lunch around 1 PM on Tuesday and the host said the kitchen wasn''t ready. We stood at the door for 20 minutes before giving up. Unwelcoming.', 'demo', '[{"party_size":null,"weekday":"tuesday","date":null,"time":"13:00","item":null,"text":"quick lunch around 1 PM on Tuesday","type":"date_time"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"the host said the kitchen wasn''t ready","type":"staff"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"stood at the door for 20 minutes","type":"wait_time"}]'::jsonb),
((select id from public.restaurants where is_template), 'm3', 'Jordan P.', 1, '2026-10-21T11:00:00', 'We had a reservation for 8 people on Saturday at 9 PM and they lost it, then made us wait 50 minutes for a table. Management did not care at all. Do not go here.', 'demo', '[{"party_size":8,"weekday":"saturday","date":null,"time":"21:00","item":null,"text":"reservation for 8 people on Saturday at 9 PM","type":"reservation"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"wait 50 minutes for a table","type":"wait_time"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"Management did not care at all","type":"staff"}]'::jsonb),
((select id from public.restaurants where is_template), 'b1', 'A. Smith', 1, '2026-10-20T21:30:00', 'Awful experience. We were there Saturday around 8 PM and the staff was rude, the food was cold and everything took forever. Never coming back.', 'demo', '[{"party_size":null,"weekday":"saturday","date":null,"time":"20:00","item":null,"text":"there Saturday around 8 PM","type":"date_time"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"the staff was rude","type":"staff"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"the food was cold","type":"food_quality"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"everything took forever","type":"wait_time"}]'::jsonb),
((select id from public.restaurants where is_template), 'b2', 'Lee M.', 1, '2026-10-21T06:10:00', 'Worst dinner of my life. Got sick after eating there on Friday. Filthy place and terrible food, stay away from this restaurant.', 'demo', '[{"party_size":null,"weekday":"friday","date":null,"time":null,"item":null,"text":"Got sick after eating there on Friday","type":"food_quality"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"Filthy place","type":"other"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"terrible food","type":"food_quality"}]'::jsonb),
((select id from public.restaurants where is_template), 'r1', 'Anil M.', 5, '2026-09-08T21:15:00', 'Wonderful evening. The gnocchi was perfect and the staff made our anniversary feel special. We will be back.', 'demo', null),
((select id from public.restaurants where is_template), 'r2', 'Meera K.', 4, '2026-09-10T13:40:00', 'Lovely food and a calm room. The pizza crust was great. A little loud when the big table arrived.', 'demo', null),
((select id from public.restaurants where is_template), 'r3', 'Rahul D.', 5, '2026-09-12T20:05:00', 'Best tiramisu in town. Friendly service and we were seated quickly. Highly recommend.', 'demo', null),
((select id from public.restaurants where is_template), 'r4', 'Sneha P.', 2, '2026-09-16T10:20:00', 'We came on Friday around 8 PM, party of 5. We waited 45 minutes for our mains and nobody gave us an update. The food was fine once it arrived.', 'demo', null),
((select id from public.restaurants where is_template), 'r5', 'Vikram S.', 4, '2026-09-18T18:30:00', 'Good pasta, reasonable prices and polite staff.', 'demo', null),
((select id from public.restaurants where is_template), 'r6', 'Ananya R.', 5, '2026-09-20T22:10:00', 'A perfect dinner. The salmon was cooked exactly right.', 'demo', null),
((select id from public.restaurants where is_template), 'r7', 'Kabir J.', 3, '2026-09-24T09:50:00', 'Service felt slow on Saturday evening and we waited a long time to get the bill. The food was good though.', 'demo', null),
((select id from public.restaurants where is_template), 'r8', 'Isha T.', 4, '2026-09-27T20:45:00', 'Nice calamari and a good wine list. Would come again.', 'demo', null),
((select id from public.restaurants where is_template), 'r9', 'Dev N.', 5, '2026-09-30T19:10:00', 'Great risotto, lovely staff and a spotless dining room.', 'demo', null),
((select id from public.restaurants where is_template), 'r10', 'Pooja V.', 3, '2026-10-02T11:25:00', 'An okay experience. The soup was lukewarm on Thursday night, but they replaced it quickly.', 'demo', null),
((select id from public.restaurants where is_template), 'r11', 'Arjun B.', 4, '2026-10-05T21:00:00', 'Cosy place. The margherita pizza was the highlight.', 'demo', null),
((select id from public.restaurants where is_template), 'r12', 'Nisha G.', 5, '2026-10-08T14:30:00', 'Fantastic service and a great ribeye. Thank you!', 'demo', null),
((select id from public.restaurants where is_template), 'r13', 'Rohan L.', 2, '2026-10-10T09:15:00', 'Cold lasagna on Friday around 7 PM, table of 4. They offered to reheat it but we had already lost our appetite.', 'demo', null),
((select id from public.restaurants where is_template), 'r14', 'Tara A.', 4, '2026-10-12T20:20:00', 'Friendly team and tasty gnocchi.', 'demo', null),
((select id from public.restaurants where is_template), 'b3', 'Sam R.', 1, '2026-10-21T08:40:00', 'Worst dinner of my life. Got sick after eating there on Friday. Filthy place, terrible food, avoid this restaurant.', 'demo', '[{"party_size":null,"weekday":"friday","date":null,"time":null,"item":null,"text":"Got sick after eating there on Friday","type":"food_quality"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"Filthy place","type":"other"},{"party_size":null,"weekday":null,"date":null,"time":null,"item":null,"text":"terrible food","type":"food_quality"}]'::jsonb);
